!function(e){function t(t){for(var n,a,p=t[0],d=t[1],c=t[2],f=0,m=[];f<p.length;f++)a=p[f],Object.prototype.hasOwnProperty.call(i,a)&&i[a]&&m.push(i[a][0]),i[a]=0;for(n in d)Object.prototype.hasOwnProperty.call(d,n)&&(e[n]=d[n]);for(l&&l(t);m.length;)m.shift()();return o.push.apply(o,c||[]),r()}function r(){for(var e,t=0;t<o.length;t++){for(var r,a=o[t],p=!0,d=1;d<a.length;d++)r=a[d],0!==i[r]&&(p=!1);p&&(o.splice(t--,1),e=n(n.s=a[0]))}return e}function n(t){if(a[t])return a[t].exports;var r=a[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,n),r.l=!0,r.exports}var a={},i={28:0},o=[];n.m=e,n.c=a,n.d=function(e,t,r){n.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},n.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},n.t=function(e,t){if(1&t&&(e=n(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(n.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var a in e)n.d(r,a,function(t){return e[t]}.bind(null,a));return r},n.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return n.d(t,"a",t),t},n.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},n.p="";var p=window.webpackJsonp=window.webpackJsonp||[],d=p.push.bind(p);p.push=t,p=p.slice();for(var c=0;c<p.length;c++)t(p[c]);var l=d;o.push([126,0]),r()}({126:function(e,t,r){"use strict";r.r(t);var n=r(0);Object(n.a)("de","army",r(127),r(1))},127:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车","link":"de_army#de_army_avhtv"}],"model":"250/2、251/11、251/19型半履带装甲布线与线路交换车","description":"<p>二战开始，德军就已经十分清楚战场上保持通讯的重要性，随着东线战事的发展，德军依靠人手布线已远远跟不上战场上的需求，因此在1942年，德军先后用250车体与251车体改装了不少专用于布设电话线的装甲车，型号有Sdkfz 250/2野战电话布线车和251/11野战电话布线车，同时也改装了一批配合251/11布线车进行电话换线和通讯保障的Sdkfz 251/19野战电话通讯交换车。</p><p>这些车专门负责在战场上铺设电话线路和建立有线通讯网络，维护战场上各单位的联络线路；布线车的出现，大大增强了德军在战场前沿布线效率和线路畅通率，保证了德军战场上的有效指挥和战斗协调。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_avhtv25xl_11.jpg","description":"<h6>Sdkfz 250/2型半履带装甲野战电话布线车</h6><p>Sdkfz 250/2战斗全重5.45吨，属小型布线车，主要用250早期车体改装；该车核载乘员4人，含1名驾驶员和3名布线通讯兵，车上配备1挺前置的MG34机枪，车厢内安装有一个电话线缆的卷轴支架，车头挡泥板两端也各加装了一个电话线缆的卷轴支架（个别车会省略），在副驾驶座后还放置有4个备用的电话线缆卷轴支架。布线时，车上布线员可在布线车行进时使用一根长杆将卷轴中的电话线缆往地面或树上进行铺设。</p><p>250/2布线车主要装备到装甲掷弹兵部队或装甲侦察部队下属营或连的通讯保障分队，通常与营、连指挥官的装甲指挥车同行。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv25xl_12.jpg","description":"<h6>Sdkfz 251/11型半履带装甲野战电话布线车</h6><p>Sdkfz 251/11战斗全重8.5吨，属中型布线车，主要用251 C型车体改装；该车核载乘员5人，含1 名驾驶员和4名布线通讯兵，车上配备2挺MG34或MG42机枪，备弹2100发，车上安置了3个电话线缆的卷轴支架，2 个在车厢内，另1个在在车头右侧挡泥板上；车上还备有一支布线用的长杆，布线员可在布线车行进时在车上使用长杆将卷轴中的电话线缆往地面或树上进行铺设。</p><p>Sdkfz 251/11在1942年8月开始装备德军，负责前沿阵地野战电话线的敷设。</p>","caption":""},{"image":"{{image}}imgs/de/army/de_army_avhtv25xl_13.jpg{{text}}251/19车上的设备与图中德军一个野战通讯保障小组设备基本相同，包括一部电话交换机和2部电话。{{image}}imgs/de/army/de_army_avhtv25xl_14.jpg","description":"<h6>Sdkfz 251/19型半履带装甲野战电话通讯交换车</h6><p>Sdkfz 251/19主要用251 D型车体改装；是专门布置在前沿阵地附近，配合布线车作野战电话换线的的通讯中转车，该车核载乘员5人，含1 名驾驶员、通讯小组的负责军官1名和3名电话换线兵，车上配备2挺MG42机枪，备弹2100发，车上有1部电话交换机、2部接线电话和电话线接线设备，251/19一般会跟随251/11布线车，停驻在各条线路的节点位置，将已铺设好的各条电话线路接入车上的换线设备，成为德军一个移动式的通讯保障车。</p>","caption":""}],"part2title":"战场上的250/2、251/11、251/19型半履带装甲布线与线路交换车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv25xl_21.jpg","description":"一辆德军小型Sdkfz 250/2半履带装甲野战电话布线车正在作布线操作，车上的一名布线兵正用一条长杆将车头滚轴的线缆往地上铺设。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xl_22.jpg","description":"1944年12月，西线德国战场，一辆被德军第9装甲师遗弃的Sdkfz 250/2半履带装甲野战电话布线车，两名美军正在对该车进行检查。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xl_23.jpg","description":"1944年2月，东线苏联战场乌克兰地区，隶属德军第8装甲师的一辆用251 D型车体改装的Sdkfz 251/11半履带装甲野战电话布线车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25xl_24.jpg","description":"一辆德军Sdkfz 250/11半履带装甲野战电话布线车正在作布线操作，车上的一名布线兵正用一条长杆将车头滚轴的线缆往树上铺设。","caption":""}]}')}});